class Solution:
    def minDistance(self, houses: List[int], k: int) -> int:
        houses.sort()
        n = len(houses)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + houses[i]

        def cost(i, j):
            m = (i + j) // 2
            med = houses[m]
            return (pre[j + 1] - pre[m]) - med * (j - m + 1) + med * (m - i) - (pre[m] - pre[i])

        from functools import lru_cache
        @lru_cache(None)
        def dp(i, m):
            if i == n:
                return 0
            if m == 1:
                return cost(i, n - 1)
            best = float('inf')
            for j in range(i, n):
                best = min(best, cost(i, j) + dp(j + 1, m - 1))
            return best

        return dp(0, k)

