class Solution {
public:
    int minDistance(vector<int>& houses, int k) {
        sort(houses.begin(), houses.end());
        int n = houses.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + houses[i];
        auto cost = [&](int i, int j) -> long long {
            int m = (i + j) / 2;
            long long med = houses[m];
            return (pre[j + 1] - pre[m]) - med * (j - m + 1) + med * (m - i) - (pre[m] - pre[i]);
        };
        vector<vector<long long>> memo(n, vector<long long>(k + 1, -1));
        function<long long(int,int)> dp = [&](int i, int m) -> long long {
            if (i == n) return 0;
            if (m == 1) return cost(i, n - 1);
            auto &res = memo[i][m];
            if (res != -1) return res;
            res = LLONG_MAX;
            for (int j = i; j < n; j++)
                res = min(res, cost(i, j) + dp(j + 1, m - 1));
            return res;
        };
        return (int)dp(0, k);
    }
};

