class Solution {
    private int[] h;
    private long[] pre;
    private Long[][] memo;
    private int n;

    public int minDistance(int[] houses, int k) {
        Arrays.sort(houses);
        n = houses.length;
        h = houses;
        pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + houses[i];
        memo = new Long[n][k + 1];
        return (int) dp(0, k);
    }

    private long cost(int i, int j) {
        int m = (i + j) / 2;
        long med = h[m];
        return (pre[j + 1] - pre[m]) - med * (j - m + 1) + med * (m - i) - (pre[m] - pre[i]);
    }

    private long dp(int i, int m) {
        if (i == n) return 0;
        if (m == 1) return cost(i, n - 1);
        if (memo[i][m] != null) return memo[i][m];
        long best = Long.MAX_VALUE;
        for (int j = i; j < n; j++)
            best = Math.min(best, cost(i, j) + dp(j + 1, m - 1));
        return memo[i][m] = best;
    }
}

