var minDistance = function(houses, k) {
    houses.sort((a, b) => a - b);
    const n = houses.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + houses[i];
    const cost = (i, j) => {
        const m = (i + j) >> 1, med = houses[m];
        return (pre[j + 1] - pre[m]) - med * (j - m + 1) + med * (m - i) - (pre[m] - pre[i]);
    };
    const memo = Array.from({length: n}, () => new Array(k + 1).fill(-1));
    const dp = (i, m) => {
        if (i === n) return 0;
        if (m === 1) return cost(i, n - 1);
        if (memo[i][m] !== -1) return memo[i][m];
        let best = Infinity;
        for (let j = i; j < n; j++)
            best = Math.min(best, cost(i, j) + dp(j + 1, m - 1));
        return memo[i][m] = best;
    };
    return dp(0, k);
};

