        INF = float('inf')
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for j in range(1, n + 1):
            for m in range(1, min(j, k) + 1):
                for i in range(m - 1, j):
                    if dp[i][m - 1] < INF:
                        dp[j][m] = min(dp[j][m], dp[i][m - 1] + cost(i, j - 1))
        return dp[n][k]

