class Solution {
    public int minDistance(int[] houses, int k) {
        Arrays.sort(houses);
        int n = houses.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + houses[i];
        long[][] cost = new long[n][n];
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                int m = (i + j) / 2;
                long med = houses[m];
                cost[i][j] = (pre[j + 1] - pre[m]) - med * (j - m + 1)
                           + med * (m - i) - (pre[m] - pre[i]);
            }
        long INF = Long.MAX_VALUE / 2;
        long[][] dp = new long[n + 1][k + 1];
        for (long[] row : dp) Arrays.fill(row, INF);
        dp[0][0] = 0;
        for (int j = 1; j <= n; j++)
            for (int m = 1; m <= Math.min(j, k); m++)
                for (int i = m - 1; i < j; i++)
                    dp[j][m] = Math.min(dp[j][m], dp[i][m - 1] + cost[i][j - 1]);
        return (int) dp[n][k];
    }
}

